CREATE TABLE IF NOT EXISTS gis_acquisition_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_key text NOT NULL, authority_name text NOT NULL, request_type text NOT NULL, purpose text NOT NULL, requested_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'DRAFT', official_contact text, official_request_url text, notes text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_received_artifacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), acquisition_request_id uuid NOT NULL REFERENCES gis_acquisition_requests(id) ON DELETE CASCADE, source_reference text NOT NULL, artifact_name text NOT NULL, artifact_format text NOT NULL, source_version text, received_at timestamptz NOT NULL DEFAULT now(), content_hash text NOT NULL, provenance_status text NOT NULL DEFAULT 'UNVERIFIED', certification_status text NOT NULL DEFAULT 'UNVERIFIED', notes text);